const body = $input.first().json.body ?? {};
const uid = String(body.uid ?? '');
const text = String(body.text ?? '').trim();
const photoKey = String(body.photoKey ?? '').slice(0, 200);

let error = null;
if (!/^[a-z0-9]{24}$/.test(uid)) error = 'Invalid session.';
else if (!text) error = 'Write a message first.';
else if (text.length > 1000) error = 'Keep messages under 1000 characters.';

return [{ json: { ok: !error, status: 400, error, uid, event: 'message', text, hasPhoto: body.hasPhoto === true, photoKey } }];

