const input = $('Chat input').first().json;
const out = $('Parse reply').first().json;
return [
  { json: { uid: input.uid, role: 'user', text: input.text, brief: '' } },
  { json: { uid: input.uid, role: 'assistant', text: out.reply, brief: out.brief ? JSON.stringify(out.brief) : '' } },
];

const body = $input.first().json.body ?? {};
const uid = String(body.uid ?? '');
const action = String(body.action ?? '');
const email = String(body.email ?? '').trim().toLowerCase();
const code = String(body.code ?? '').trim();

let error = null;
if (!/^[a-z0-9]{24}$/.test(uid)) error = 'Invalid session.';
else if (!['start', 'verify', 'pro'].includes(action)) error = 'Unknown action.';
else if (action === 'start' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) error = 'Enter a valid email.';
else if (action === 'verify' && !/^\d{6}$/.test(code)) error = 'Enter the 6-digit code.';

const newCode = String(Math.floor(100000 + Math.random() * 900000));
return [{ json: { ok: !error, status: 400, error, uid, action, email, code, newCode } }];

const item = $input.first();
const body = item.json.body ?? {};
const photo = item.binary?.photo;
const uid = String(body.uid ?? '');

let error = null;
if (!/^[a-z0-9]{24}$/.test(uid)) error = 'Invalid session.';
else if (!photo) error = 'Attach a product photo.';
else if (!String(photo.mimeType ?? '').startsWith('image/')) error = 'Photo must be an image.';

const photoName = String(photo?.fileName ?? 'Product photo').slice(0, 120);
return [{
  json: { ok: !error, status: 400, error, uid, photoName, photoKey: photoName + '-' + String(photo?.fileSize ?? '') },
  binary: item.binary,
}];

// The model returns JSON; fall back to plain text so a formatting slip never breaks the chat.
const raw = String($input.first().json.output ?? '').trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
let out;
try {
  out = JSON.parse(raw);
} catch {
  out = { reply: raw, brief: null };
}
const b = out.brief;
const brief = b && b.title && b.description
  ? { title: String(b.title).slice(0, 80), description: String(b.description).slice(0, 600) }
  : null;
const reply = String(out.reply ?? '').trim() || 'Tell me a little more about your product.';
return [{ json: { reply, brief } }];
